  return {
    async createShow(show) {
      await db
        .prepare(
          `INSERT INTO shows (id, device_id, title, venue, performed_at, duration_seconds,
             audio_key, byte_size, content_type, status, created_at, updated_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
